(() => {
  const $ = s => document.querySelector(s);
  // index.html is the Super Admin / Seller console; player.html is the page sellers share with buyers (Player Details + Quiz only).
  const PLAYER = document.body.dataset.page === 'player';
  const num = v => { const n = parseFloat(String(v).replace(/[,\s₹]/g, '')); return isFinite(n) ? n : NaN; };
  const round2 = n => Math.round(n * 100) / 100;
  const fmt = n => '₹' + n.toLocaleString('en-IN', Number.isInteger(n) ? {} : { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const SAMPLE_IMG = 'data:image/jpeg;base64,';
  const SAMPLE = {
    shop: 'Desai Toys', cc: 'IN', phone: '98765 43210', pname: 'Wooden Rainbow Stacker (7 pieces)',
    desc: 'Handmade from neem wood with non-toxic colours. Helps toddlers learn colours, sizes and balance. Ages 1 to 5.',
    mrp: '1499', pct: 20, img: SAMPLE_IMG, imgName: 'rainbow-stacker.jpg (example)',
  };
  const state = { img: null, imgName: '', saved: false, published: false, role: PLAYER ? 'buyer' : 'admin' };
  const TABS_FOR = { admin: [1, 2, 3], seller: [1, 2, 3], buyer: [2, 3] };
  const ROLE_NOTE = {
    admin: 'Previewing as Super Admin: sees all 3 tabs and every player entry.',
    seller: 'Previewing as Seller: sets up Tab 1 and can check scores for any date in Tab 2.',
    buyer: 'Previewing as Buyer: fills in Player Details (Tab 2), then stays on the Quiz (Tab 3) until the next day.',
  };

  // ---------- tabs ----------
  // Tabs open in order: Tab 2 after the seller saves Tab 1, Tab 3 after a player starts in Tab 2.
  // A buyer who has entered today's quiz stays on Tab 3 until the date changes.
  const buyerLocked = () => state.role === 'buyer' && !!play.me;
  const tabOpen = i => i === 3 ? !!(play.me || play.pastMe) : buyerLocked() ? false : i === 1 || (i === 2 && state.published);
  const LOCK_TIP = { 2: 'Opens after Seller\'s Details are saved', 3: 'Opens after you start the quiz in Player Details' };
  const lockTip = i => buyerLocked() && i !== 3 ? 'You have entered today\'s quiz. A new quiz opens after 00:00:00.' : LOCK_TIP[i];
  function refreshTabs() {
    [2, 3].forEach(i => {
      const b = $('#tab-' + i), open = tabOpen(i);
      b.disabled = !open; b.title = open ? '' : lockTip(i);
      b.querySelector('.lock') || b.insertAdjacentHTML('beforeend', '<span class="lock" aria-hidden="true">🔒</span>');
      b.querySelector('.lock').hidden = open;
    });
  }
  function showTab(n) {
    const allowed = TABS_FOR[state.role].filter(tabOpen);
    if (!allowed.includes(n)) n = allowed.length ? allowed[allowed.length - 1] : 0;
    state.tab = n;
    refreshTabs();
    if (n === 2) renderTab2();
    if (n === 3) renderTab3();
    [0, 1, 2, 3].forEach(i => {
      if (i && $('#tab-' + i)) $('#tab-' + i).setAttribute('aria-selected', String(i === n));
      if ($('#panel-' + i)) $('#panel-' + i).hidden = i !== n;
    });
  }
  const askConfirm = text => new Promise(res => {
    const d = $('#confirmDlg');
    $('#confirmText').textContent = text;
    d.returnValue = '';
    d.addEventListener('close', () => res(d.returnValue === 'yes'), { once: true });
    d.showModal();
  });
  [1, 2, 3].forEach(i => $('#tab-' + i) && $('#tab-' + i).addEventListener('click', () => showTab(i)));
  function setRole(r) {
    state.role = r;
    document.querySelectorAll('.roles button').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.role === r)));
    [1, 2, 3].forEach(i => { if ($('#tab-' + i)) $('#tab-' + i).hidden = !TABS_FOR[r].includes(i); });
    $('.tabs').classList.toggle('two', TABS_FOR[r].length === 2);
    if ($('#roleNote')) $('#roleNote').textContent = ROLE_NOTE[r];
    showTab(TABS_FOR[r].includes(state.tab) ? state.tab : TABS_FOR[r][TABS_FOR[r].length - 1]);
  }
  document.querySelectorAll('.roles button').forEach(b => b.addEventListener('click', () => setRole(b.dataset.role)));
  document.addEventListener('click', e => { const b = e.target.closest('[data-tab]'); if (b) showTab(+b.dataset.tab); });

  // ======================= Tab 1 (console only) =======================
  let readForm = () => ({});
  function initSellerForm() {
  // ---------- validation ----------
  const touched = new Set();
  const ccOpt = () => $('#cc').selectedOptions[0];
  const digits = () => { let d = $('#phone').value.replace(/\D/g, ''); if (d.length > 1 && d[0] === '0') d = d.slice(1); return d; };
  const isCoupon = () => $('#ptCoupon').checked;
  const rules = {
    shop: () => { const v = $('#shop').value.trim(); return !v ? 'Enter your shop name.' : v.length < 2 ? 'Shop name must be at least 2 characters.' : ''; },
    phone: () => {
      const o = ccOpt(), d = digits(), raw = $('#phone').value.trim();
      if (!raw) return 'Enter a phone number buyers can call.';
      if (/[^\d\s()+-]/.test(raw)) return 'Use digits only.';
      if (d.length !== +o.dataset.len) return `Numbers for ${o.value} have ${o.dataset.len} digits after ${o.dataset.code}.`;
      if (!o.dataset.start.includes(d[0])) return `Mobile numbers for ${o.value} start with ${o.dataset.start.split('').join(', ')}.`;
      return '';
    },
    pname: () => { const v = $('#pname').value.trim(); return !v ? 'Enter the product name.' : v.length < 3 ? 'Product name must be at least 3 characters.' : ''; },
    img: () => state.img ? '' : 'Add a product image.',
    desc: () => { const v = $('#desc').value.trim(); return !v ? 'Describe the product.' : v.length < 20 ? 'Write at least 20 characters so buyers know what they can win.' : v.length > 500 ? 'Keep the description to 500 characters.' : ''; },
    mrp: () => { if (isCoupon()) return ''; const n = num($('#mrp').value); return !$('#mrp').value.trim() ? 'Enter the MRP.' : isNaN(n) || n <= 0 ? 'MRP must be a number above 0.' : n > 1000000 ? 'MRP must be ₹10,00,000 or less.' : ''; },
    win: () => {
      if (isCoupon()) return '';
      const m = num($('#mrp').value), w = num($('#winPrice').value);
      if (!$('#winPrice').value.trim()) return 'Enter the price the winner pays.';
      if (isNaN(w) || w < 0) return 'Winner price must be a number.';
      if (!isNaN(m) && w >= m) return 'Winner price must be lower than the MRP.';
      return '';
    },
    pct: () => { if (isCoupon()) return ''; const p = num($('#pct').value); return isNaN(p) ? 'Enter a discount.' : p < 5 || p > 90 ? 'Discount must be between 5% and 90%.' : ''; },
  };
  const fieldFor = { shop: '#shop', phone: '#phone', pname: '#pname', img: '#drop', desc: '#desc', mrp: '#mrp', win: '#winPrice', pct: '#pct' };
  const errFor = { shop: '#shopErr', phone: '#phoneErr', pname: '#pnameErr', img: '#imgErr', desc: '#descErr', mrp: '#mrpErr', win: '#winErr', pct: '#pctErr' };
  function check(all) {
    let firstBad = null;
    Object.keys(rules).forEach(k => {
      const msg = rules[k](), show = (all || touched.has(k)) ? msg : '';
      $(errFor[k]).textContent = show;
      $(fieldFor[k]).classList.toggle('invalid', !!show);
      $(fieldFor[k]).setAttribute('aria-invalid', String(!!show));
      if (msg && !firstBad) firstBad = k;
    });
    return firstBad;
  }
  Object.entries(fieldFor).forEach(([k, sel]) => {
    const el = $(sel);
    // Skip when focus is moving to a button, so errors appearing don't shift the button away mid-click; submit checks everything anyway.
    el.addEventListener('blur', e => { touched.add(k); if (!(e.relatedTarget && e.relatedTarget.tagName === 'BUTTON')) check(); });
  });

  // ---------- discount <-> winner price ----------
  function fromPct() {
    const m = num($('#mrp').value), p = num($('#pct').value);
    if (!isNaN(m) && !isNaN(p)) $('#winPrice').value = String(Math.round(m * (1 - p / 100))); // whole rupees
  }
  function fromWin() {
    const m = num($('#mrp').value), w = num($('#winPrice').value);
    if (!isNaN(m) && m > 0 && !isNaN(w)) {
      const p = round2((1 - w / m) * 100);
      $('#pct').value = String(p);
      $('#pctRange').value = String(Math.min(90, Math.max(5, Math.round(p))));
    }
  }
  $('#pctRange').addEventListener('input', () => { $('#pct').value = $('#pctRange').value; touched.add('pct'); fromPct(); update(); });
  $('#pct').addEventListener('input', () => { const p = num($('#pct').value); if (!isNaN(p)) $('#pctRange').value = String(Math.min(90, Math.max(5, Math.round(p)))); fromPct(); update(); });
  $('#mrp').addEventListener('input', () => { fromPct(); update(); });
  $('#winPrice').addEventListener('input', () => { fromWin(); update(); });
  // Winner's prize: either the MRP / Winner pays price or a discount coupon (5% steps). Only the chosen one reaches player.html.
  function setPrizeType() {
    const c = isCoupon();
    ['#mrp', '#winPrice', '#pct', '#pctRange'].forEach(s => $(s).disabled = c);
    ['#coupon', '#couponRange'].forEach(s => $(s).disabled = !c);
    $('#priceBox').classList.toggle('off', c); $('#couponBox').classList.toggle('off', !c);
    update();
  }
  ['#ptPrice', '#ptCoupon'].forEach(s => $(s).addEventListener('change', setPrizeType));
  $('#couponRange').addEventListener('input', () => { $('#coupon').value = $('#couponRange').value; update(); });
  $('#coupon').addEventListener('change', () => { $('#couponRange').value = $('#coupon').value; update(); });
  ['#shop', '#phone', '#pname', '#desc', '#cc'].forEach(s => $(s).addEventListener('input', update));
  $('#cc').addEventListener('change', () => { $('#phone').placeholder = { IN: '98765 43210', AE: '50 123 4567', US: '(201) 555-0123', GB: '7400 123456', AU: '412 345 678', SG: '8123 4567' }[$('#cc').value]; update(); });

  // ---------- image upload ----------
  const MAX = 2 * 1024 * 1024;
  function setImage(src, name) {
    state.img = src; state.imgName = name;
    $('#thumb').innerHTML = src ? `<img alt="">` : 'No image';
    if (src) $('#thumb img').src = src;
    $('#imgName').textContent = src ? name : 'Drop a photo here or click to choose';
    $('#imgRemove').hidden = !src;
    touched.add('img'); update();
  }
  function takeFile(f) {
    if (!f) return;
    if (!/^image\/(jpeg|png|webp)$/.test(f.type)) { $('#imgErr').textContent = 'That file type is not supported. Use a JPG, PNG or WebP image.'; return; }
    if (f.size > MAX) { $('#imgErr').textContent = `That image is ${(f.size / 1048576).toFixed(1)} MB. Use one under 2 MB.`; return; }
    const r = new FileReader();
    r.onload = () => setImage(r.result, f.name);
    r.readAsDataURL(f);
  }
  $('#drop').addEventListener('click', e => { if (!e.target.closest('#imgRemove')) $('#file').click(); });
  $('#drop').addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); $('#file').click(); } });
  $('#file').addEventListener('change', e => { takeFile(e.target.files[0]); e.target.value = ''; });
  ['dragenter', 'dragover'].forEach(ev => $('#drop').addEventListener(ev, e => { e.preventDefault(); $('#drop').classList.add('over'); }));
  ['dragleave', 'drop'].forEach(ev => $('#drop').addEventListener(ev, e => { e.preventDefault(); $('#drop').classList.remove('over'); }));
  $('#drop').addEventListener('drop', e => takeFile(e.dataTransfer.files[0]));
  $('#imgRemove').addEventListener('click', e => { e.stopPropagation(); setImage(null, ''); });

  // ---------- live preview ----------
  function update() {
    state.saved = false; $('#formMsg').textContent = ''; $('#formMsg').className = 'msg';
    const shop = $('#shop').value.trim(), name = $('#pname').value.trim(), desc = $('#desc').value.trim();
    const m = num($('#mrp').value), w = num($('#winPrice').value), p = num($('#pct').value);
    const len = $('#desc').value.trim().length;
    $('#descCount').textContent = `${len} / 500`;
    $('#descCount').classList.toggle('over', len > 500);
    $('#pvShop').textContent = shop || 'Your shop';
    $('#pvName').textContent = name || 'Product name';
    $('#pvDesc').textContent = desc || 'Product description';
    const d = digits();
    $('#pvPhone').textContent = d ? `${ccOpt().dataset.code} ${d.replace(/(\d{5})(\d+)/, '$1 $2')}` : 'Phone number';
    const cp = +$('#coupon').value, coupon = isCoupon();
    const ribbon = coupon ? `Winner gets a ${cp}% coupon` : !isNaN(p) && p > 0 ? `Winner gets ${round2(p)}% off` : '';
    $('#pvImg').innerHTML = (state.img ? '<img alt="">' : '<span>Product image</span>') + (ribbon ? `<span class="ribbon">${ribbon}</span>` : '');
    if (state.img) { const im = $('#pvImg img'); im.src = state.img; im.alt = name || 'Prize product'; }
    const okPrice = !isNaN(m) && m > 0 && !isNaN(w) && w < m;
    $('#pvWin').textContent = okPrice ? fmt(w) : (!isNaN(m) ? fmt(m) : '₹0');
    $('#pvMrp').textContent = okPrice ? fmt(m) : '';
    $('#pvSave').textContent = okPrice ? `Save ${fmt(round2(m - w))}` : '';
    if (coupon) {
      $('#pvWin').textContent = `${cp}% off coupon`; $('#pvMrp').textContent = ''; $('#pvSave').textContent = 'for the winner';
    }
    $('#pvNote').textContent = coupon ? 'Only the quiz winner gets the discount coupon for your products. Everyone else pays the usual price.' : "Only the quiz winner can buy at the winner's price. Everyone else sees the MRP.";
    $('#couponCalc').innerHTML = `The winner gets a <b>${cp}% discount coupon</b> for your products.`;
    $('#calc').innerHTML = okPrice
      ? `MRP ${fmt(m)} &minus; <b>${round2(p)}%</b> = winner pays <b>${fmt(w)}</b> (saves ${fmt(round2(m - w))})`
      : 'Enter the MRP and a discount to see what the winner pays.';
    check();
  }

  // ---------- save ----------
  $('#sellerForm').addEventListener('submit', async e => {
    e.preventDefault();
    Object.keys(rules).forEach(k => touched.add(k));
    const bad = check(true);
    if (bad) {
      $('#formMsg').className = 'msg bad';
      $('#formMsg').textContent = 'Fix the highlighted fields to continue.';
      $(fieldFor[bad]).focus();
      return;
    }
    if (!await askConfirm(`Buyers will see "${$('#pname').value.trim()}" from ${$('#shop').value.trim()} as today's prize. A Player page with Player Details and the Quiz will be created for you to share.`)) return;
    state.saved = state.published = true;
    $('#formMsg').className = 'msg ok';
    $('#formMsg').textContent = `Saved. Buyers will see "${$('#pname').value.trim()}" from ${$('#shop').value.trim()} as the winner's prize.`;
    $('#tab-1').classList.add('done');
    refreshTabs();
    await makePlayerLink();
  });
  $('#resetBtn').addEventListener('click', () => {
    ['#shop', '#phone', '#pname', '#desc', '#mrp', '#winPrice', '#pct'].forEach(s => $(s).value = '');
    $('#pctRange').value = 20; touched.clear(); $('#tab-1').classList.remove('done');
    $('#ptPrice').checked = true; $('#coupon').value = $('#couponRange').value = '10'; setPrizeType();
    setImage(null, ''); touched.clear(); check(); update();
    $('#shareBox').hidden = true;
  });


  // ---------- player.html link ----------
  // The prize travels inside the link (#o=...), so player.html needs no server. The image is shrunk to keep the link short.
  function shrink(src) {
    return new Promise(res => {
      const im = new Image();
      im.onload = () => {
        const k = Math.min(1, 360 / Math.max(im.width, im.height)), c = document.createElement('canvas');
        c.width = Math.round(im.width * k); c.height = Math.round(im.height * k);
        const x = c.getContext('2d'); x.fillStyle = '#ffffff'; x.fillRect(0, 0, c.width, c.height); x.drawImage(im, 0, 0, c.width, c.height);
        res(c.toDataURL('image/jpeg', 0.72));
      };
      im.onerror = () => res(null);
      im.src = src;
    });
  }
  async function makePlayerLink() {
    const o = readForm();
    o.img = state.img ? await shrink(state.img) : null;
    const url = new URL('player.html', location.href).href.split('#')[0] + '#o=' + packOffer(o);
    $('#shareUrl').value = url; $('#openLink').href = url;
    $('#shareBox').hidden = false;
    $('#shareBox').scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  }
  $('#copyLink').addEventListener('click', () => {
    const b = $('#copyLink'), done = t => { b.textContent = t; setTimeout(() => { b.textContent = 'Copy link'; }, 1600); };
    const pick = () => { $('#shareUrl').select(); done('Select and copy'); };
    try { navigator.clipboard.writeText($('#shareUrl').value).then(() => done('Copied'), pick); } catch (_) { pick(); }
  });
  readForm = () => {
    const d = digits(), m = num($('#mrp').value), w = num($('#winPrice').value);
    return { shop: $('#shop').value.trim(), phone: d ? `${ccOpt().dataset.code} ${d.replace(/(\d{5})(\d+)/, '$1 $2')}` : '',
      pname: $('#pname').value.trim(), desc: $('#desc').value.trim(), img: state.img,
      ...(isCoupon() ? { type: 'coupon', coupon: +$('#coupon').value } : { type: 'price', mrp: m, win: w, pct: round2(num($('#pct').value)) }) };
  };
  // start with an example filled in
  $('#shop').value = SAMPLE.shop; $('#cc').value = SAMPLE.cc; $('#phone').value = SAMPLE.phone; $('#phone').placeholder = '98765 43210';
  $('#pname').value = SAMPLE.pname; $('#desc').value = SAMPLE.desc; $('#mrp').value = SAMPLE.mrp;
  $('#pct').value = SAMPLE.pct; $('#pctRange').value = SAMPLE.pct; fromPct();
  $('#coupon').value = $('#couponRange').value = '10';
  setImage(SAMPLE.img, SAMPLE.imgName); touched.clear(); setPrizeType();
  }

  // ======================= Tab 2 + Tab 3 =======================
  const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const dayStr = (off = 0) => { const d = new Date(); d.setDate(d.getDate() + off); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); };
  const today = () => dayStr(0);
  const niceDate = s => new Date(s + 'T00:00:00').toLocaleDateString(undefined, { dateStyle: 'medium' });
  const mmss = s => Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0');
  // Public view: name and phone fully hidden, email shown as first letter + ***** on giazonest.com for everyone.
  const maskEmail = e => (e[0] || 'x').toLowerCase() + '*****@giazonest.com';
  const QUIZ_SECONDS = 300, PER_Q = 20;

  // Question source (not shown to users). questions.js holds a Class VII bank; every player gets a fresh random 9.
  const QUIZ_SOURCE = 'https://ttc-quizzes.github.io/ttc-quiz-portal/';
  const QBANK = window.GIAZO_QBANK || [];
  // Prefer questions this browser hasn't seen recently, so a replay or the next player on the same device gets new ones.
  const SEEN_KEY = 'giazo-seen-q';
  function pickQuestions(n) {
    let seen = [];
    try { seen = JSON.parse(localStorage.getItem(SEEN_KEY) || '[]'); } catch (e) {}
    const shuffle = a => { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
    const ids = [...QBANK.keys()], fresh = shuffle(ids.filter(i => !seen.includes(i))), old = shuffle(ids.filter(i => seen.includes(i)));
    const pick = fresh.concat(old).slice(0, n);
    try { localStorage.setItem(SEEN_KEY, JSON.stringify(seen.filter(i => !pick.includes(i)).concat(pick).slice(-Math.floor(QBANK.length * .7)))); } catch (e) {}
    return pick.map(i => QBANK[i]);
  }
  // Like NXTROI's wheel, each segment carries one letter of the brand name.
  const WHEEL_WORD = 'GIAZONEST';
  const WCOL = ['#F2591B', '#1C4FC4', '#232B33', '#4F8A2A', '#8A5A2B', '#7A5BB5', '#C7410E', '#1E7F4F', '#B8336A'];

  // Today's entries (example rows). Each has a date; anything not from today is removed at 00:00:00.
  const play = {
    entries: [
      { name: 'Neha Patil', email: 'neha.patil@gmail.com', phone: '+91 98200 11223', date: today(), status: 'done', score: 80, secs: 151 },
      { name: 'Sameer Joshi', email: 'sameer.j@outlook.com', phone: '+91 99300 44556', date: today(), status: 'done', score: 80, secs: 188 },
      { name: 'Tanvi Rao', email: 'tanvi.rao@yahoo.com', phone: '+971 50 123 4567', date: today(), status: 'done', score: 60, secs: 132 },
      { name: 'Arjun Bose', email: 'arjun.bose@gmail.com', phone: '+91 90040 77889', date: today(), status: 'playing', score: null, secs: null },
    ],
    me: null, pastMe: null, run: null, day: today(),
    // Closed days (example data). At 00:00:00 today's entries move here and become public results.
    history: {
      [dayStr(-1)]: { shop: 'Desai Toys', prod: 'Wooden Rainbow Stacker (7 pieces)', pct: 20, entries: [
        { name: 'Kavya Iyer', email: 'kavya.iyer@gmail.com', phone: '+91 98450 12345', status: 'done', score: 100, secs: 164 },
        { name: 'Rohit Mehra', email: 'rohit.m@gmail.com', phone: '+91 98111 22334', status: 'done', score: 80, secs: 140 },
        { name: 'Fatima Shaikh', email: 'fatima.s@outlook.com', phone: '+971 55 765 4321', status: 'done', score: 80, secs: 201 },
        { name: 'Dev Malhotra', email: 'dev.malhotra@yahoo.com', phone: '+91 97000 55667', status: 'done', score: 40, secs: 297 },
      ] },
      [dayStr(-2)]: { shop: 'Desai Toys', prod: 'Wooden Shape Sorter Box', pct: 25, entries: [
        { name: 'Ishaan Gupta', email: 'ishaan.g@gmail.com', phone: '+91 99880 11002', status: 'done', score: 80, secs: 122 },
        { name: 'Meera Nair', email: 'meera.nair@gmail.com', phone: '+91 94470 33221', status: 'done', score: 60, secs: 175 },
        { name: 'Aman Verma', email: 'aman.verma@hotmail.com', phone: '+91 98990 77665', status: 'playing', score: null, secs: null },
      ] },
      [dayStr(-3)]: { shop: 'Desai Toys', prod: 'Wooden Rainbow Stacker (7 pieces)', pct: 15, entries: [
        { name: 'Pooja Kulkarni', email: 'pooja.k@gmail.com', phone: '+91 90280 44556', status: 'done', score: 100, secs: 98 },
        { name: 'Nikhil Das', email: 'nikhil.das@gmail.com', phone: '+91 98300 99887', status: 'done', score: 100, secs: 131 },
      ] },
    },
  };
  const rankList = list => list.filter(e => e.status === 'done').sort((a, b) => b.score - a.score || a.secs - b.secs);

  // Today's prize: from the Seller's Details form in the console, or from the shared link on player.html.
  const packOffer = o => { const b = new TextEncoder().encode(JSON.stringify(o)); let s = ''; for (let i = 0; i < b.length; i += 8192) s += String.fromCharCode.apply(null, b.subarray(i, i + 8192)); return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); };
  const unpackOffer = t => { const s = atob(t.replace(/-/g, '+').replace(/_/g, '/')); return JSON.parse(new TextDecoder().decode(Uint8Array.from(s, c => c.charCodeAt(0)))); };
  let linkOffer = null;
  const offer = () => PLAYER ? (linkOffer || {}) : readForm();
  // How the winner's prize reads: "at 20% off" (MRP / Winner pays) or "with a 10% discount coupon".
  const isCouponOffer = o => o.type === 'coupon';
  const prizeShort = o => isCouponOffer(o) ? `with a ${o.coupon}% discount coupon` : `at ${round2(o.pct)}% off`;
  function prizeMini() {
    const o = offer(), name = o.pname || 'Prize product', shop = o.shop || 'Seller';
    const m = o.mrp, w = o.win, p = o.pct;
    const price = isCouponOffer(o) ? `Winner gets a <span class="w">${o.coupon}% discount coupon</span>`
      : !isNaN(m) && !isNaN(w) && w < m ? `Winner pays <span class="w">${fmt(w)}</span> <s>${fmt(m)}</s> (${round2(p)}% off)` : '';
    return (o.img ? `<img src="${o.img}" alt="">` : '<span></span>') + `<div><span>Today's prize from ${esc(shop)}</span><b>${esc(name)}</b><span>${price}</span></div>`;
  }

  // ---------- midnight countdown + automatic reset ----------
  function untilMidnight() {
    const n = new Date(), m = new Date(n); m.setHours(24, 0, 0, 0);
    const s = Math.max(0, Math.floor((m - n) / 1000));
    return [Math.floor(s / 3600), Math.floor(s / 60) % 60, s % 60].map(x => String(x).padStart(2, '0')).join(':');
  }
  function dailyReset(note) {
    // Close yesterday: keep its entries as results, then clear the form's list for the new date.
    const old = play.entries.filter(e => e.date !== today());
    if (old.length) play.history[play.day] = { shop: offer().shop, prod: offer().pname, pct: offer().pct, prize: prizeShort(offer()), entries: old };
    play.entries = play.entries.filter(e => e.date === today());
    if (play.me && !play.entries.includes(play.me)) { stopRun(); if (play.me.status === 'playing') play.me.status = 'unfinished'; play.pastMe = play.me; play.me = null; }
    play.day = today();
    $('#date2').max = today(); $('#date2').value = today();
    $('#date3').max = dayStr(-1); $('#date3').value = dayStr(-1);
    if (note) { $('#plMsg').className = 'msg ok'; $('#plMsg').textContent = note; }
    showTab(state.tab);
  }
  setInterval(() => {
    const c = untilMidnight();
    $('#clock2').textContent = c; $('#clock3').textContent = c;
    if (today() !== play.day) dailyReset('A new day has started. Yesterday\'s entries were removed and a new quiz is open.');
  }, 1000);
  $('#clock2').textContent = $('#clock3').textContent = untilMidnight();

  // ---------- Tab 2: player entry ----------
  const EMAIL_RE = /^(?!\.)(?!.*\.\.)[A-Za-z0-9._%+'-]{1,64}(?<!\.)@(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,24}$/;
  const plDigits = () => { let d = $('#plPhone').value.replace(/\D/g, ''); if (d.length > 1 && d[0] === '0') d = d.slice(1); return d; };
  const plRules = {
    name: () => { const v = $('#plName').value.trim(); return !v ? 'Enter your name.' : v.length < 2 ? 'Name must be at least 2 characters.' : /[0-9<>]/.test(v) ? 'Use letters only in your name.' : ''; },
    email: () => { const v = $('#plEmail').value.trim(); return !v ? 'Enter your email.' : !EMAIL_RE.test(v) ? 'Enter a valid email, for example name@gmail.com.' : ''; },
    phone: () => {
      const o = $('#plCc').selectedOptions[0], d = plDigits(), raw = $('#plPhone').value.trim();
      if (!raw) return 'Enter your phone number.';
      if (/[^\d\s()+-]/.test(raw)) return 'Use digits only.';
      if (d.length !== +o.dataset.len) return `Numbers for ${o.value} have ${o.dataset.len} digits after ${o.dataset.code}.`;
      if (!o.dataset.start.includes(d[0])) return `Mobile numbers for ${o.value} start with ${o.dataset.start.split('').join(', ')}.`;
      return '';
    },
  };
  const plField = { name: '#plName', email: '#plEmail', phone: '#plPhone' };
  function plCheck(all) {
    let bad = null;
    Object.keys(plRules).forEach(k => {
      const m = plRules[k](), show = all || $(plField[k]).dataset.t ? m : '';
      $(plField[k] + 'Err').textContent = show;
      $(plField[k]).classList.toggle('invalid', !!show);
      if (m && !bad) bad = k;
    });
    return bad;
  }
  Object.values(plField).forEach(s => {
    $(s).addEventListener('blur', e => { $(s).dataset.t = '1'; if (!(e.relatedTarget && e.relatedTarget.tagName === 'BUTTON')) plCheck(); });
    $(s).addEventListener('input', () => { $('#plMsg').textContent = ''; plCheck(); });
  });
  $('#plCc').addEventListener('change', () => plCheck());

  function renderTab2() {
    $('#mini2').innerHTML = prizeMini();
    const priv = state.role !== 'buyer';
    $('#entriesPanel').hidden = !priv;
    $('#panel-2').classList.toggle('grid2', priv);
    const day = $('#date2').value || today(), isToday = day === today();
    const all = isToday ? play.entries : (play.history[day] || {}).entries || [];
    const done = rankList(all), rows = [...done, ...all.filter(e => e.status !== 'done')];
    $('#entries').innerHTML = rows.length ? rows.map(e => { const r = done.indexOf(e) + 1; return `<tr><td class="num">${r || '–'}</td><td style="white-space:nowrap">${esc(e.name)}${r === 1 ? ` <span class="pill done">${isToday ? 'Leading' : 'Winner'}</span>` : ''}</td><td>${esc(e.email)}</td><td style="white-space:nowrap">${esc(e.phone)}</td>
      <td>${e.status === 'done' ? '<span class="pill done">Finished</span>' : `<span class="pill wait">${isToday ? 'Playing' : 'Didn\'t finish'}</span>`}</td>
      <td class="num">${e.score ?? '–'}</td><td class="num">${e.secs != null ? mmss(e.secs) : '–'}</td></tr>`; }).join('')
      : `<tr><td colspan="7" class="small">${isToday ? 'No entries yet today.' : 'No quiz was played on this date.'}</td></tr>`;
    $('#entriesNote').textContent = `${rows.length} entr${rows.length === 1 ? 'y' : 'ies'} on ${niceDate(day)}.` + (isToday ? ' Scores update live. The form clears at 00:00:00 and results go public in the Quiz tab.' : '');
  }

  $('#playerForm').addEventListener('submit', async e => {
    e.preventDefault();
    const bad = plCheck(true);
    if (bad) { $('#plMsg').className = 'msg bad'; $('#plMsg').textContent = 'Fix the highlighted fields to start.'; $(plField[bad]).focus(); return; }
    const email = $('#plEmail').value.trim().toLowerCase();
    const o = $('#plCc').selectedOptions[0], d = plDigits();
    const phone = `${o.dataset.code} ${d.replace(/(\d{5})(\d+)/, '$1 $2')}`;
    const prev = play.entries.find(x => x.email === email || x.phone.replace(/\D/g, '') === phone.replace(/\D/g, ''));
    if (prev && prev.status === 'done') {
      $('#plMsg').className = 'msg bad';
      $('#plMsg').textContent = `You've already played today (${prev.score} points). Come back after 00:00:00 for the new quiz.`;
      return;
    }
    if (!await askConfirm('Your 5-minute quiz opens in the Quiz tab. You can play once today.')) return;
    play.me = prev || { name: $('#plName').value.trim().replace(/\s+/g, ' '), email, phone, date: today(), status: 'playing', score: null, secs: null };
    if (!prev) play.entries.push(play.me);
    $('#plMsg').textContent = '';
    showTab(3);
  });

  // ---------- Tab 3: wheel game ----------
  function drawWheel() {
    const c = $('#wheel'), x = c.getContext('2d'), n = WHEEL_WORD.length, R = 370, cx = 380, seg = 2 * Math.PI / n;
    const css = v => getComputedStyle(document.documentElement).getPropertyValue(v).trim();
    x.clearRect(0, 0, 760, 760);
    for (let i = 0; i < n; i++) {
      const a0 = -Math.PI / 2 + i * seg, done = play.run && play.run.done.has(i);
      x.beginPath(); x.moveTo(cx, cx); x.arc(cx, cx, R, a0, a0 + seg); x.closePath();
      x.fillStyle = done ? css('--line') : WCOL[i]; x.fill();
      x.lineWidth = 6; x.strokeStyle = css('--surface'); x.stroke();
      // Letter stands upright along the segment's centre line, reading outward from the hub.
      x.save(); x.translate(cx, cx); x.rotate(a0 + seg / 2); x.translate(R - 95, 0); x.rotate(Math.PI / 2);
      x.textAlign = 'center'; x.textBaseline = 'middle';
      x.fillStyle = done ? css('--muted') : '#ffffff';
      x.font = '800 92px Sora, sans-serif'; x.fillText(WHEEL_WORD[i], 0, 0);
      if (done) { x.font = '700 30px Manrope, sans-serif'; x.fillText('✓', 0, 70); }
      x.restore();
    }
    x.beginPath(); x.arc(cx, cx, R, 0, 2 * Math.PI); x.lineWidth = 10; x.strokeStyle = css('--ink'); x.stroke();
  }
  function stopRun() { if (play.run) { clearInterval(play.run.tick); play.run.ended = true; } play.run = null; }
  function newRun() {
    stopRun();
    play.run = { qs: pickQuestions(WHEEL_WORD.length), done: new Set(), asked: 0, score: 0, left: QUIZ_SECONDS, started: false, rot: 0, busy: false, log: [], tick: null, ended: false };
    $('#dots').innerHTML = '<i></i>'.repeat(5);
    $('#timer').textContent = mmss(QUIZ_SECONDS); $('#timer').classList.remove('low');
    $('#tbar').style.width = '100%'; $('#score').textContent = '0'; $('#qn').textContent = '0/5';
    $('#spin').disabled = false; $('#qArea').innerHTML = '';
    $('#wheel').style.transition = 'none'; $('#wheel').style.transform = 'rotate(0deg)';
    requestAnimationFrame(() => { $('#wheel').style.transition = ''; });
    drawWheel();
  }
  // Public results: only closed days (yesterday and earlier). Today's ranking stays hidden until 00:00:00.
  function renderLeaderboard() {
    const day = $('#date3').value || dayStr(-1), h = play.history[day];
    const lb = h ? rankList(h.entries) : [];
    const mine = e => play.pastMe && e.email === play.pastMe.email && day === play.pastMe.date;
    $('#lbCount').textContent = h ? `${lb.length} finished · ${h.entries.length} entered` : '';
    $('#lbNote').textContent = `Showing ${day === dayStr(-1) ? 'yesterday\'s' : 'the'} results for ${niceDate(day)}. Results for today's quiz (${niceDate(today())}) appear here after 00:00:00.`;
    $('#winner3').innerHTML = lb.length ? `<div class="winner"><span class="tag">Winner · ${niceDate(day)}</span><b>*****${mine(lb[0]) ? ' (you)' : ''} · ${maskEmail(lb[0].email)}</b><span class="small sub" style="margin:0">${lb[0].score} pts in ${mmss(lb[0].secs)}. Wins ${esc(h.prod)} ${h.prize || `at ${h.pct}% off`} from ${esc(h.shop)}.</span></div>` : '';
    $('#lb').innerHTML = lb.length ? lb.map((e, i) => `<li class="${i === 0 ? 'first' : ''} ${mine(e) ? 'me' : ''}">
      <span class="rank">${i + 1}</span>
      <span class="who"><b>*****${mine(e) ? ' (you)' : ''}</b><span>${maskEmail(e.email)} · Phone *****</span></span>
      <span class="sc"><b>${e.score} pts</b>${mmss(e.secs)}</span></li>`).join('')
      : `<li><span></span><span class="who"><span>No results for ${niceDate(day)}.</span></span><span></span></li>`;
  }
  function renderTab3() {
    $('#mini3').innerHTML = prizeMini();
    const me = play.me;
    const playing = me && me.status === 'playing';
    $('#game').hidden = !playing;
    $('#result').hidden = !!playing;
    if (!me && play.pastMe) $('#result').innerHTML = `<div class="wait-card"><b>The quiz from ${niceDate(play.pastMe.date)} has ended</b><span class="small sub" style="margin:0">The results are below. To play today's quiz, enter your details again in Player Details.</span></div>`;
    if (playing && !play.run) newRun();
    if (!playing) $('#qArea').innerHTML = '';
    renderLeaderboard();
  }

  function startClock() {
    const r = play.run; r.started = true;
    r.tick = setInterval(() => {
      r.left--; $('#timer').textContent = mmss(Math.max(0, r.left));
      $('#timer').classList.toggle('low', r.left <= 30);
      $('#tbar').style.width = (Math.max(0, r.left) / QUIZ_SECONDS * 100) + '%';
      if (r.left <= 0) finish("Time's up");
    }, 1000);
  }
  $('#spin').addEventListener('click', () => {
    const r = play.run; if (!r || r.busy || r.asked >= 5) return;
    if (!r.started) startClock();
    r.busy = true; $('#spin').disabled = true;
    const n = WHEEL_WORD.length, seg = 360 / n, free = [...Array(n).keys()].filter(i => !r.done.has(i));
    const i = free[Math.floor(Math.random() * free.length)];
    const target = (360 - (i + .5) * seg + ((Math.random() - .5) * seg * .6) + 360) % 360;
    const cur = ((r.rot % 360) + 360) % 360; r.rot += 5 * 360 + ((target - cur + 360) % 360);
    $('#wheel').style.transform = `rotate(${r.rot}deg)`;
    $('#qArea').innerHTML = '<div class="qcard"><span class="tag">Spinning…</span><h3>Where will it land?</h3></div>';
    const ms = matchMedia('(prefers-reduced-motion:reduce)').matches ? 350 : 4300;
    setTimeout(() => ask(i), ms);
  });
  function ask(i) {
    const r = play.run; if (!r || r.ended) return;
    const q = r.qs[i]; r.asked++;
    $('#qn').textContent = `${r.asked}/5`;
    $('#qArea').innerHTML = `<div class="qcard"><span class="tag">Letter ${WHEEL_WORD[i]} · Question ${r.asked} of 5 · ${esc(q.t)} · +${PER_Q} pts</span><h3>${esc(q.q)}</h3>
      <div class="opts">${q.o.map((o, k) => `<button type="button" class="opt" data-k="${k}"><b>${'ABCD'[k]}</b>${esc(o)}</button>`).join('')}</div><div id="ex"></div></div>`;
    $('#qArea').querySelectorAll('.opt').forEach(b => b.addEventListener('click', () => answer(i, +b.dataset.k)));
  }
  function answer(i, k) {
    const r = play.run, q = r.qs[i], ok = k === q.a;
    $('#qArea').querySelectorAll('.opt').forEach(b => { b.disabled = true; const kk = +b.dataset.k; if (kk === q.a) b.classList.add('right'); else if (kk === k) b.classList.add('wrong'); });
    if (ok) r.score += PER_Q;
    $('#score').textContent = r.score;
    $('#dots').children[r.asked - 1].className = ok ? 'r' : 'w';
    r.log.push({ q, k, ok }); r.done.add(i); drawWheel();
    $('#ex').innerHTML = `<p class="msg ${ok ? 'ok' : 'bad'}" style="margin:0">${ok ? 'Correct.' : 'Not quite.'} ${esc(q.e)}</p>
      <button type="button" class="btn" id="next" style="margin-top:10px">${r.asked < 5 ? 'Spin again' : 'See results'}</button>`;
    $('#next').addEventListener('click', () => {
      if (r.asked >= 5) return finish('Quiz complete');
      r.busy = false; $('#spin').disabled = false; $('#qArea').innerHTML = ''; $('#spin').click();
    });
  }
  function finish(why) {
    const r = play.run, me = play.me; if (!r || r.ended || !me) return;
    r.ended = true; clearInterval(r.tick);
    const used = QUIZ_SECONDS - Math.max(0, r.left);
    me.status = 'done'; me.score = r.score; me.secs = used;
    const right = r.log.filter(l => l.ok).length;
    const prod = offer().pname || 'the prize';
    $('#result').innerHTML = `<div><h2>${why}: ${r.score} points</h2><p class="sub">${right} of 5 correct in ${mmss(used)}. Your score is saved.</p></div>` +
      `<div class="wait-card"><b>Results are announced after 00:00:00</b><span class="small sub" style="margin:0">Come back to this tab after midnight to see the winner of ${esc(prod)} ${prizeShort(offer())}. The seller contacts the winner on the phone number they entered.</span></div>` +
      `<div style="display:grid;gap:8px">${r.log.map((l, n) => `<div class="qcard"><span class="tag">Q${n + 1} · ${l.ok ? 'Correct' : 'Wrong'}</span><div>${esc(l.q.q)}</div><span class="small sub" style="margin:0">Answer: ${esc(l.q.o[l.q.a])}</span></div>`).join('') || '<p class="small sub">No questions answered before time ran out.</p>'}</div>`;
    play.run = null;
    renderTab3();
  }

  $('#date2').max = today(); $('#date2').value = today();
  $('#date3').max = dayStr(-1); $('#date3').value = dayStr(-1);
  $('#date2').addEventListener('change', renderTab2);
  $('#today2').addEventListener('click', () => { $('#date2').value = today(); renderTab2(); });
  $('#date3').addEventListener('change', renderLeaderboard);
  if (PLAYER) {
    try { const m = location.hash.match(/^#o=([A-Za-z0-9_-]+)/); linkOffer = m ? unpackOffer(m[1]) : null; } catch (_) { linkOffer = null; }
    if (linkOffer && !(linkOffer.shop && linkOffer.pname)) linkOffer = null;
    if (linkOffer) {
      state.published = true;
      $('#playerShop').textContent = `Today's prize from ${linkOffer.shop}` + (linkOffer.phone ? ` · ${linkOffer.phone}` : '');
      document.title = `${linkOffer.shop} · Giazo Quiz Reward`;
    }
    setRole('buyer');
  } else {
    initSellerForm();
    setRole('admin');
  }
})();
